{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Para achar a finalidade de um texto, pergunte: quem fala, sobre o quê e para quê? Em cartazes de divulgação, o título e o nome do projeto dizem muito. A alternativa certa une o problema social (violência contra mulheres) ao lugar onde o texto o coloca (a escola). Ela não pode ir além do que está escrito.",
      "motivo": "Frases mais curtas e sem o parêntese que repetia termo do glossário."
    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "A: feminicídio? C: comparação?\nD: segurança? E: estudos?",
      "motivo": "A conta original era uma lista seca de palavras, sem indicar a letra de cada uma. Assim, o aluno associa cada letra ao teste."
    },
    {
      "campo": "resolucao.passos[3].porque",
      "depois": "O texto não fala de feminicídio e não compara meninas e meninos. \"Segurança\" aparece só em \"segurança e qualidade de vida\" e no selo do Anuário. Nenhuma dessas ideias é o foco do cartaz.",
      "motivo": "Simplifica a frase longa e deixa claro por que cada letra cai."
    },
    {
      "campo": "resolucao.passos[4].conta",
      "depois": "violência de gênero + escola\n= engajar o setor educacional",
      "motivo": "A conta original era longa para a tela do celular; agora está em duas linhas curtas."
    },
    {
      "campo": "resolucao.erradas.A",
      "depois": "O texto fala de \"violência de gênero\" e \"violência contra mulheres\", não de feminicídio (assassinato de mulheres). A hashtag \"#DESAFIO igualdade\" é só um selo lateral. Falta ver que o foco é a escola, não uma campanha virtual.",
      "motivo": "Explica o termo feminicídio, cuja diferença é a chave da letra, e diz o que faltou no raciocínio."
    },
    {
      "campo": "resolucao.erradas.D",
      "depois": "\"Segurança\" aparece só no selo do Anuário e em \"segurança e qualidade de vida\". O texto quer falar do tema na escola, não proteger estudantes lá. Quem marcou D pegou uma palavra solta em vez do propósito do cartaz.",
      "motivo": "Mostra o que faltou no raciocínio de quem marcou D."
    }
  ],
  "didatica_alertas": [],
  "didatica_ok": true
}
